// Build-time memo (CR-729): every page of `next build` reads the live board, and each release reader re-validates its whole
// predecessor chain, so the build cost grows with the square of the release count. Inside `next build` only (NEXT_PHASE),
// the fully validated v1.8.23 bundle is kept per root and per worker process and every caller gets a deep copy. Tests, the
// validator's negative controls and the runtime server never set NEXT_PHASE and keep the uncached, fully re-validated path.
const V1823_BUILD_CACHE=new Map();
const v1823BuildCacheOn=()=>process.env.NEXT_PHASE==='phase-production-build';
const copyV1823Release=r=>{if(!r)return r;const{bytes,...rest}=r;return{...structuredClone(rest),bytes};};
export async function readOptionalJevbenchV1823Release(root=process.cwd()){
 if(!v1823BuildCacheOn())return readJevbenchV1823ReleaseUncached(root);
 const key=String(root);
 if(!V1823_BUILD_CACHE.has(key)){const p=readJevbenchV1823ReleaseUncached(root);V1823_BUILD_CACHE.set(key,p);p.catch(()=>V1823_BUILD_CACHE.delete(key));}
 return copyV1823Release(await V1823_BUILD_CACHE.get(key));
}
export async function readJevbenchV1823Candidate(root=process.cwd()){return readJevbenchV1823ReleaseUncached(root,{candidate:true});}
async function readJevbenchV1823ReleaseUncached(root,opts={}){
 let publication;try{publication=await load(V1823_MANIFEST,root);}catch(e){if(e.code==='ENOENT')return null;throw e;}
 const previous=await (opts.candidate?readJevbenchV1822Candidate(root):readOptionalJevbenchV1822Release(root));if(!previous)fail('validated predecessor');
 const predecessor=await load(`${V1823_ROOT}/jevbench-v1.8.22-publication.json`,root);
 const b=Object.fromEntries(await Promise.all(V1823_FILE_KEYS.map(async k=>[k,await load(`${V1823_ROOT}/jevbench-v1.8.23-${k}.json`,root)])));
 for(const[k,v]of Object.entries(b))if(v.sha256!==publication.value.files[k]?.sha256)fail('bytes hash '+k);
 for(const k of ['carry','history','history-carry'])if(b[k].sha256!==previous.manifest.files[k].sha256)fail('immutable '+k);
 validateJevbenchV1823Bundle({manifest:publication.value,artifact:b.results.value,categories:b.categories.value,carry:b.carry.value,proof:b.proof.value,previous,previousManifestSha256:predecessor.sha256},opts);
 return {artifact:b.results.value,bytes:b.results.bytes,sha256:b.results.sha256,categories:b.categories.value,categoriesSha256:b.categories.sha256,carry:b.carry.value,carrySha256:b.carry.sha256,proof:b.proof.value,manifest:publication.value,historical:previous.historical};
}
export async function readJevbenchV1823ForBoard(root=process.cwd()){
 let p;try{p=(await load(V1823_MANIFEST,root)).value;}catch(e){if(e.code==='ENOENT')return null;throw e;}
 return p?.review?.verdict==='PASS'?readOptionalJevbenchV1823Release(root):null;
}
export async function hasPublishedJevbenchV1823Release(root=process.cwd(),log=console.error){try{return Boolean(await readJevbenchV1823ForBoard(root));}catch{log('JevBench v1.8.23 navigation omitted: publication validation failed');return false;}}
export const V1823_BREAKDOWN_NOTE='Breakdown values are shown for cells with at least 30 scored items; more items are being added.';
// Display adapter only: frozen category artifacts and all score/rank fields stay untouched.
export function v1823CategoryDisplay(categories){
 const systems=Object.fromEntries(Object.entries(categories.systems).map(([k,r])=>[k,{...r,...Object.fromEntries(['topics','usecases','languages'].filter(d=>r[d]).map(d=>[d,Object.fromEntries(Object.entries(r[d]).filter(([,c])=>c.n>=30 && (c.coverage_n??c.n)>=30))]))}]));
 return withRowPoolCategoryRows({...categories,systems:{},min_n:30,display_min_n:30,rules:[...(categories.rules??[]),V1823_BREAKDOWN_NOTE]},systems,apiFullAddendumCategoryBounds(categories)??{});
}
// Project legacy row breakdowns at the same display floor; never mutate the frozen results.
const dropSmallRowBreakdowns=(value,inBreakdowns=false)=>{
 if(!value||typeof value!=='object')return value;
 if(Array.isArray(value))return value.map(v=>dropSmallRowBreakdowns(v,inBreakdowns));
 return Object.fromEntries(Object.entries(value).filter(([k,v])=>!(inBreakdowns&&v&&typeof v==='object'&&Number.isInteger(v.n)&&v.n<30)).map(([k,v])=>[k,dropSmallRowBreakdowns(v,inBreakdowns||k==='breakdowns')]));
};
export function v1823BoardInput(release,chain){
 const bounds={...apiFullAddendumCategoryBounds(chain?.categories),...structuredClone(V1823_NEW_ROW_BOUNDS)};
 const categories=withRowPoolCategoryRows({...release.categories,systems:{}},release.categories.systems,bounds);
 return {artifact:{...release.artifact,systems:release.artifact.systems.map(s=>dropSmallRowBreakdowns(s))},categories:v1823CategoryDisplay(categories)};
}
export function withV1823Addendum(chain,release){
 const update=a=>({...a,systems:release.artifact.systems.map(s=>dropSmallRowBreakdowns(s)),board:release.artifact.board,n_ranked:release.artifact.n_ranked,roster_count:release.artifact.roster_count,not_measured:release.artifact.not_measured,measurement_notes:release.artifact.measurement_notes,restated_by:'v1.8.23',v1823_sha256:release.sha256});
 const {categories}=v1823BoardInput(release,chain);
 const adapted=withRowPoolCategoryRows({...categories,revision:chain.published.revision,restated_by:'v1.8.23',systems:{}},categories.systems,apiFullAddendumCategoryBounds(categories));
 return {...chain,published:update(chain.published),merged:update(chain.merged),categories:adapted,publishedCarry:release.carry};
}
